
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_mgga_xc_b0kcis_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_mgga_xc_b0kcis", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.290970351090559e+00, -3.229216617466470e+00, -3.142732890520654e+00, -3.023032442381018e+00, -2.860137683083428e+00, -2.643783408657973e+00, -2.366244984505823e+00, -2.027398569607421e+00, -1.641341846843882e+00, -1.238671113611748e+00, -8.478911667834234e-01, -5.742912079592021e-01, -4.944220012270817e-01, -4.043379238132458e-01, -2.955502301366609e-01, -1.930554293910300e-01, -1.184190483522590e-01, -7.220328125669435e-02, -4.576540398376525e-02, -3.129012892344207e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


